<template><view class="words-section" v-if="lesson.vocabWords?.length">
 <text class="words-kicker">{{lesson.level||'ENGLISH'}} VOCABULARY</text><text class="words-heading">KEY WORDS FROM THE ARTICLE</text>
 <view class="words-box"><text class="words-help">Tap a word to explore its meaning and context.</text>
 <view v-for="(word,index) in lesson.vocabWords.slice(0,12)" :key="word" class="word-row">
  <button class="word-trigger" :disabled="!!busy && busy!==word" @click="toggle(word)"><text class="word-number">{{Number(index)+1}}</text><text class="word-name">{{word}}</text><text class="word-pos" v-if="entries[word]">{{entries[word].pos}}</text><text class="word-expand">{{selected===word?'−':'+'}}</text></button>
  <view v-if="selected===word" class="word-details"><text v-if="busy===word" class="word-loading">Finding the right words…</text><text v-else-if="errors[word]" class="word-error" @click="load(word)">{{errors[word]}} · Retry</text><template v-else-if="entries[word]"><text class="word-definition">{{entries[word].meaningCn}}</text><text class="word-example">“{{entries[word].example}}”</text><view class="word-actions"><text @click="$emit('locate',word)">Find in transcript ↗</text><button class="word-save" @click="save(word)">{{store.isSaved(word)?'✓ Saved':'＋ Save word'}}</button></view></template></view>
 </view></view>
 <view class="words-practice"><text class="practice-title">MAKE THESE WORDS YOURS</text><text class="practice-caption">Save your words, flip the cards, then try a quick quiz.</text><button class="practice-cta" @click="review">START PRACTICE →</button></view>
</view></template>
<script setup lang="ts">
import {ref} from 'vue';
import {studyContent,studyError} from '@/utils/api';
import {useVocabStore} from '@/stores/vocab';
const props=defineProps<{lesson:any}>();
defineEmits(['locate']);
const store=useVocabStore();store.load();
const selected=ref(''),busy=ref(''),entries=ref<Record<string,any>>({}),errors=ref<Record<string,string>>({});
function toggle(word:string){selected.value=selected.value===word?'':word;if(selected.value&&!entries.value[word])load(word)}
async function load(word:string){if(busy.value)return;busy.value=word;errors.value={...errors.value,[word]:''};try{const result=await studyContent(props.lesson.id,'word',{word});entries.value={...entries.value,[word]:result}}catch(e){errors.value={...errors.value,[word]:studyError(e)}}finally{busy.value=''}}
function save(word:string){const entry=entries.value[word];if(!entry)return;const sentences=props.lesson.paragraphs.flatMap((p:any)=>p.sentences);try{store.toggle({word,pos:entry.pos||'',meaningCn:entry.meaningCn,example:entry.example,lessonId:props.lesson.id,lessonTitle:props.lesson.title,sentenceIndex:sentences.findIndex((s:any)=>s.text===entry.example)})}catch(e){uni.showToast({title:'Unable to save this word. Try again.',icon:'none'})}}
function review(){uni.reLaunch({url:'/pages/profile/vocab'})}
</script>
<style scoped>
.words-section{margin:48rpx 0 40rpx}.words-kicker{display:inline-block;background:#27854d;color:#fff;font-size:17rpx;padding:6rpx 11rpx;border-radius:5rpx;font-weight:650;letter-spacing:1rpx}.words-heading{display:block;font-family:ListHeading,sans-serif;font-size:41rpx;color:#246336;font-weight:700;letter-spacing:.3rpx;line-height:1.06;margin:12rpx 0 24rpx}.words-box{border:1rpx solid #dce7df;border-radius:16rpx;overflow:hidden;box-shadow:0 5rpx 12rpx rgba(28,72,40,.035)}.words-help{display:block;background:#f4faf6;color:#829c89;padding:22rpx 24rpx;font-size:23rpx;line-height:1.5}.word-row{border-top:1rpx solid #e5ede7}.word-trigger{margin:0;padding:24rpx 23rpx;display:flex;align-items:center;gap:14rpx;background:#fff;border:0;border-radius:0;text-align:left}.word-number{height:33rpx;width:33rpx;min-width:33rpx;line-height:29rpx;border:1rpx solid #8fc39f;color:#5e986f;border-radius:50%;text-align:center;font-size:19rpx;background:#f0f9f2}.word-name{color:#2d7844;font-weight:650;font-size:29rpx}.word-pos{color:#99ada0;font-size:21rpx;font-style:italic;overflow:hidden}.word-expand{margin-left:auto;color:#81ae8f;font-size:31rpx;font-weight:400}.word-details{padding:0 26rpx 23rpx}.word-definition{display:block;font-size:26rpx;color:#7d8b81;line-height:1.7}.word-example{display:block;font-family:Georgia,serif;font-size:27rpx;font-style:italic;color:#8d9890;line-height:1.6;margin-top:12rpx}.word-actions{display:flex;align-items:center;justify-content:space-between;gap:15rpx;margin-top:22rpx;font-size:20rpx;color:#88a38f}.word-actions .word-save{margin:0;border:1rpx solid #cfe2d5;background:#f1f8f3;padding:11rpx 15rpx;border-radius:10rpx;font-size:21rpx;color:#548260}.word-loading,.word-error{color:#98aba0;font-size:24rpx;line-height:1.6}.words-practice{background:#eff9f2;border:1rpx solid #c9e4d1;border-radius:16rpx;padding:25rpx;margin-top:25rpx}.practice-title{font-family:ListHeading,sans-serif;display:block;font-size:32rpx;color:#2e7241}.practice-caption{font-size:23rpx;line-height:1.6;color:#7f9b88;display:block;margin:11rpx 0 22rpx}.words-practice .practice-cta{background:#27854d;color:#fff;font-size:23rpx;font-weight:600;padding:22rpx;border-radius:11rpx;letter-spacing:1rpx}
</style>
